local runtimeUrl = "https://cdn.project-reverse.org/builder/mm2/v1/main.luau"
local function fetchRuntime()
    local lastError
    for attempt = 1, 3 do
        local ok, result = pcall(function() return game:HttpGet(runtimeUrl, true) end)
        if ok and type(result) == "string" and #result > 0 then return result end
        lastError = result
        if attempt < 3 then task.wait(0.35 * attempt) end
    end
    error("MM2 runtime download failed: " .. tostring(lastError))
end
local source = fetchRuntime()
local chunk, compileError = loadstring(source)
assert(chunk, "MM2 runtime compile failed: " .. tostring(compileError))
local run = chunk()
assert(type(run) == "function", "MM2 runtime entrypoint is invalid")
local genv = (typeof(getgenv) == "function") and getgenv() or _G
if type(genv.ProjectReverseHub) == "table" and type(genv.ProjectReverseHub.destroy) == "function" then
    pcall(function() genv.ProjectReverseHub.destroy() end)
end
local controller = run(config)
assert(type(controller) == "table" and type(controller.destroy) == "function", "MM2 runtime did not start; inspect the executor console")
genv.ProjectReverseHub = controller
return controller
